// GENERATED by scripts/sync-guard.mjs from the repository root. Do not edit here: change the original and run `node scripts/sync-guard.mjs`.
// Agent Office does not invent tool policy. Sessions run on Claude Code's own engine with the same settings a plain `claude` run
// would load, so allow / deny / ask rules, permission mode, additionalDirectories, hooks, MCP servers, CLAUDE.md, skills, plugins
// and env all come from the user's configuration. The only requests that reach this file are the ones Claude Code itself would
// prompt for ("ask"); they are shown to the user in the UI with Claude Code's own choices (Yes, Yes and don't ask again, No with an
// optional instruction) and the answer is handed back unchanged.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

// The three scopes Claude Code reads, as a plain `claude` run from this directory does.
export const SETTING_SOURCES = ['user', 'project', 'local'];

const readJson = f => { try { return JSON.parse(fs.readFileSync(f, 'utf8')); } catch { return {}; } };

// permissions.defaultMode as Claude Code resolves it: local overrides project overrides user.
export function readDefaultMode({ cwd = process.cwd(), home = os.homedir() } = {}) {
  const files = [path.join(cwd, '.claude', 'settings.local.json'), path.join(cwd, '.claude', 'settings.json'), path.join(home, '.claude', 'settings.json')];
  for (const f of files) { const m = readJson(f)?.permissions?.defaultMode; if (typeof m === 'string' && m) return m; }
  return undefined;
}

// The environment a plain `claude` would get: ours, minus what only the Electron shell and this app use. Settings env is applied by
// Claude Code itself (it reads the same settings files); it is not merged here.
export function cleanEnv(env = process.env) {
  const out = { ...env };
  delete out.ELECTRON_RUN_AS_NODE;
  for (const k of Object.keys(out)) if (/^AGENT_OFFICE_(UI_KEY|BOOT|GUARD_KEY)/.test(k)) delete out[k];
  return out;
}

// Options every Claude Code session (Tiro and the agents it hires) starts with. Nothing here narrows or widens what the user's
// own config decides: no permissionMode (the SDK picks it exactly as `claude -p` does from settings), no model or effort, the
// full claude_code tool preset (Bash, PowerShell, NotebookEdit, TodoWrite, Skill, AskUserQuestion ...), no MCP isolation.
// Only bypassPermissions needs the SDK's explicit opt-in, and only when the user's config asks for it.
export function claudeSessionOptions({ cwd, home = os.homedir(), env = process.env, claudeExe, extra = {} } = {}) {
  const mode = readDefaultMode({ cwd, home });
  return {
    cwd,
    settingSources: [...SETTING_SOURCES],
    tools: { type: 'preset', preset: 'claude_code' },
    env: { ...cleanEnv(env), AGENT_OFFICE_SDK_SESSION: '1' },   // the Guard SDK hook already runs here; the plugin command hook exits early
    ...(mode === 'bypassPermissions' ? { allowDangerouslySkipPermissions: true } : {}),
    ...(claudeExe ? { pathToClaudeCodeExecutable: claudeExe } : {}),
    ...extra,
  };
}

// Hire gate, command side: a sub-agent started from a shell skips request_hire, so a Bash/PowerShell command that launches Claude
// itself is denied in Tiro's session with a pointer to request_hire. Deny-only: it never approves anything.
export const launchesClaude = cmd => /(^|[;&|(]\s*|[\\/]|\bnpx\s+(?:-\w+\s+)*|\b(?:start|call|exec|env)\s+)["']?claude(?:\.exe|\.cmd|\.ps1)?(?=\s|$|["')])|@anthropic-ai\/(?:claude-code|claude-agent-sdk)|claude-agent-sdk/i.test(String(cmd ?? ''));

const isQuestion = t => t === 'AskUserQuestion';

// Everything the user needs to decide, as Claude Code would show it: the full tool input, why it asked, and the options it offers.
export function describeRequest(tool, input, opts = {}) {
  const i = input && typeof input === 'object' ? input : {};
  const summary = tool === 'Bash' || tool === 'PowerShell' ? String(i.command ?? '')
    : isQuestion(tool) ? 'Claude asks you a question'
    : i.file_path ? `${tool}: ${i.file_path}` : i.url ? `${tool}: ${i.url}` : i.pattern ? `${tool}: ${i.pattern}` : tool;
  const preview = tool === 'Write' ? String(i.content ?? '')
    : /^(Edit|MultiEdit)$/.test(tool) ? JSON.stringify(i.edits ?? { old: i.old_string, new: i.new_string }, null, 1)
    : tool === 'Bash' || tool === 'PowerShell' || isQuestion(tool) ? '' : JSON.stringify(i, null, 1);
  const suggestions = Array.isArray(opts.suggestions) ? opts.suggestions : [];
  const questions = isQuestion(tool) && Array.isArray(i.questions)
    ? i.questions.slice(0, 4).map(q => ({ question: String(q?.question ?? ''), header: String(q?.header ?? ''), multiSelect: !!q?.multiSelect, options: (Array.isArray(q?.options) ? q.options : []).slice(0, 8).map(o => ({ label: String(o?.label ?? ''), description: String(o?.description ?? '') })) }))
    : undefined;
  return {
    toolUseId: opts.toolUseID || '', cmd: summary, short: tool, why: opts.decisionReason || '', title: opts.title || '', displayName: opts.displayName || '', description: opts.description || '',
    blockedPath: opts.blockedPath || '', preview: preview.slice(0, 20000),
    canAlways: suggestions.length > 0 && !opts.suppressAlwaysAllowRule && !questions, // "yes and don't ask again" = Claude Code's own suggested rule
    defaultToNo: !!opts.defaultToNo,
    ...(questions ? { questions } : {}),
  };
}

// The permission callback. ask(agentId, tool, input, details) must return a promise of
// { decision: 'allow' | 'deny' | 'terminal', always?, message?, answers? } and may expose p.cancel().
export function makeCanUseTool({ ask, agentOf }) {
  return async (tool, toolInput, opts = {}) => {
    const { signal, suggestions, agentID, toolUseID, suppressAlwaysAllowRule } = opts;
    const p = ask(agentOf(agentID), tool, toolInput, describeRequest(tool, toolInput, opts));
    signal?.addEventListener('abort', () => p.cancel?.(), { once: true });
    const r = await p;
    if (r.decision === 'allow') {
      if (isQuestion(tool)) {
        const answers = r.answers && typeof r.answers === 'object' ? Object.fromEntries(Object.entries(r.answers).map(([k, v]) => [String(k), String(v)])) : null;
        if (!answers || !Object.keys(answers).length) return { behavior: 'deny', message: 'The user did not answer the question.', toolUseID };
        return { behavior: 'allow', updatedInput: { ...toolInput, answers }, toolUseID };
      }
      return {
        behavior: 'allow',
        updatedInput: toolInput, // never edited after the rules were checked
        // Same permission update Claude Code suggested, to the scope it suggested (user, project or local settings).
        updatedPermissions: r.always && !suppressAlwaysAllowRule && suggestions?.length ? suggestions : undefined,
        toolUseID,
      };
    }
    return { behavior: 'deny', message: r.message || (r.decision === 'terminal' ? 'No answer from Agent Office.' : 'The user denied this action in Agent Office.'), toolUseID };
  };
}
